namespace sv_b669af5662834cd8a33f723ccb416d2e.Services;

/// <summary>
/// Scoped service (per-circuit in Blazor Server) that holds the current warehouse
/// selection and notifies subscribers when it changes. Each user circuit gets its
/// own independent instance.
/// </summary>
public sealed class WarehouseStateService : IDisposable
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } = new List<(string, string)>
    {
        ("WH-001", "Warehouse A — Downtown"),
        ("WH-002", "Warehouse B — Airport"),
        ("WH-003", "Warehouse C — Harbor"),
    };

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public void Dispose()
    {
        OnWarehouseChanged = null;
    }
}

namespace sv_b669af5662834cd8a33f723ccb416d2e.Services;

/// <summary>
/// Simulates querying a database for low-stock item counts.
/// Registered as scoped so each circuit gets its own instance with independent state.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();
    private int _lastCount;
    private string? _lastWarehouseId;

    public int LastKnownCount => _lastCount;

    /// <summary>
    /// Event raised when a new poll result is available. All subscribed components
    /// receive the notification regardless of which component triggered the poll.
    /// </summary>
    public event Action<int>? OnAlertCountUpdated;

    /// <summary>
    /// Simulates a database query returning items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        _lastCount = count;
        _lastWarehouseId = warehouseId;
        OnAlertCountUpdated?.Invoke(count);
        return Task.FromResult(count);
    }
}

@using sv_b669af5662834cd8a33f723ccb416d2e.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="text-nowrap mb-0 fw-semibold" for="warehouse-select">Site:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@using sv_b669af5662834cd8a33f723ccb416d2e.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="badge @BadgeClass rounded-pill">@_count</span>

@code {
    private int _count;

    private string BadgeClass => _count switch
    {
        0 => "bg-success",
        <= 5 => "bg-warning text-dark",
        _ => "bg-danger"
    };

    protected override void OnInitialized()
    {
        _count = AlertService.LastKnownCount;
        AlertService.OnAlertCountUpdated += HandleAlertUpdate;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void HandleAlertUpdate(int newCount)
    {
        _count = newCount;
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        // Reset count display until next poll delivers fresh data
        _count = 0;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountUpdated -= HandleAlertUpdate;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_b669af5662834cd8a33f723ccb416d2e.Services
@using sv_b669af5662834cd8a33f723ccb416d2e.Components.Shared
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Current Site: @CurrentWarehouseName
        </h5>
        <p class="card-text">
            Low-Stock Alerts: <AlertBadge />
        </p>
        <p class="text-muted small">
            Polling every 10 seconds. Last checked: @_lastPoll.ToString("HH:mm:ss")
        </p>
    </div>
</div>

<div class="card">
    <div class="card-header">Inventory Status</div>
    <div class="card-body">
        <p>
            Items below minimum stock threshold for
            <strong>@CurrentWarehouseName</strong>:
            <span class="fs-4 fw-bold text-danger">@_alertCount</span>
        </p>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastPoll = DateTime.Now;
    private CancellationTokenSource? _cts;

    private string CurrentWarehouseName =>
        WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        ?? WarehouseState.CurrentWarehouseId;

    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.OnAlertCountUpdated += HandleAlertUpdate;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await PollOnce();
            StartPolling();
        }
    }

    private void StartPolling()
    {
        _cts?.Cancel();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            while (!token.IsCancellationRequested)
            {
                await Task.Delay(TimeSpan.FromSeconds(10), token);
                if (token.IsCancellationRequested) break;
                await InvokeAsync(async () =>
                {
                    await PollOnce();
                    StateHasChanged();
                });
            }
        }, token);
    }

    private async Task PollOnce()
    {
        _alertCount = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
        _lastPoll = DateTime.Now;
    }

    private void HandleWarehouseChanged()
    {
        // Restart polling immediately for the new warehouse
        InvokeAsync(async () =>
        {
            _cts?.Cancel();
            await PollOnce();
            StateHasChanged();
            StartPolling();
        });
    }

    private void HandleAlertUpdate(int count)
    {
        _alertCount = count;
        _lastPoll = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.OnAlertCountUpdated -= HandleAlertUpdate;
    }
}

